plugins {
    id("sift.plugin-conventions")
    alias(libs.plugins.run.paper)
}

base {
    archivesName.set("TheSift")
}

// The datapack generated by packgen (pack-src/datapack) ships inside the jar; the bootstrapper
// installs it into plugins/TheSift/datapack and registers it with Paper
tasks.processResources {
    from(rootDir.resolve("pack-src/datapack")) {
        into("datapack")
    }
    // custom block <-> vanilla state mapping and the German names (fallback for item names)
    from(rootDir.resolve("pack-src/block-mapping.json"))
    from(rootDir.resolve("pack-src/resourcepack-overlay/assets/the_sift/lang/de_de.json")) {
        into("lang")
    }
}

tasks.runServer {
    minecraftVersion(libs.versions.minecraft.get())
    javaLauncher.set(javaToolchains.launcherFor {
        languageVersion.set(JavaLanguageVersion.of(25))
    })
}
